{"source_evidence": {"v4.3.0:doRetryNotify": {"source_path": "retry.go", "revision": "720b78985a65c0452fd37bb155c7cac4157a7c45", "source_sha256": "b21e168bb7e9cef042818138ed24658db1ad314ef740218dc3b61725e2cd3212", "first_line": 70, "last_line": 118, "quote": "func doRetryNotify[T any](operation OperationWithData[T], b BackOff, notify Notify, t Timer) (T, error) {
	var (
		err  error
		next time.Duration
		res  T
	)
	if t == nil {
		t = &defaultTimer{}
	}

	defer func() {
		t.Stop()
	}()

	ctx := getContext(b)

	b.Reset()
	for {
		res, err = operation()
		if err == nil {
			return res, nil
		}

		var permanent *PermanentError
		if errors.As(err, &permanent) {
			return res, permanent.Err
		}

		if next = b.NextBackOff(); next == Stop {
			if cerr := ctx.Err(); cerr != nil {
				return res, cerr
			}

			return res, err
		}

		if notify != nil {
			notify(err, next)
		}

		t.Start(next)

		select {
		case <-ctx.Done():
			return res, ctx.Err()
		case <-t.C():
		}
	}
}"}, "v4.3.0:WithContext": {"source_path": "context.go", "revision": "720b78985a65c0452fd37bb155c7cac4157a7c45", "source_sha256": "b7884b0062bafb41eb9f7032f64704a55280fd6fc6a42d260c50637582982514", "first_line": 23, "last_line": 39, "quote": "func WithContext(b BackOff, ctx context.Context) BackOffContext { // nolint: golint
	if ctx == nil {
		panic("nil context")
	}

	if b, ok := b.(*backOffContext); ok {
		return &backOffContext{
			BackOff: b.BackOff,
			ctx:     ctx,
		}
	}

	return &backOffContext{
		BackOff: b,
		ctx:     ctx,
	}
}"}, "v4.3.0:getContext": {"source_path": "context.go", "revision": "720b78985a65c0452fd37bb155c7cac4157a7c45", "source_sha256": "b7884b0062bafb41eb9f7032f64704a55280fd6fc6a42d260c50637582982514", "first_line": 41, "last_line": 49, "quote": "func getContext(b BackOff) context.Context {
