}"}, "v4.3.0:backOffTries.NextBackOff": {"source_path": "tries.go", "revision": "720b78985a65c0452fd37bb155c7cac4157a7c45", "source_sha256": "4dfae8898960edaf75a4d0c75deb7fd49b04b7ea06d7d665fc9043a411040ed8", "first_line": 22, "last_line": 33, "quote": "func (b *backOffTries) NextBackOff() time.Duration {
	if b.maxTries == 0 {
		return Stop
	}
	if b.maxTries > 0 {
		if b.maxTries <= b.numTries {
			return Stop
		}
		b.numTries++
	}
	return b.delegate.NextBackOff()
}"}, "v4.3.0:ExponentialBackOff.NextBackOff": {"source_path": "exponential.go", "revision": "720b78985a65c0452fd37bb155c7cac4157a7c45", "source_sha256": "cd5e77b2c07db015cae3d8ad5224600f73db66b8d5f8bf1f75b73051689ddcfc", "first_line": 171, "last_line": 180, "quote": "func (b *ExponentialBackOff) NextBackOff() time.Duration {
	// Make sure we have not gone over the maximum elapsed time.
	elapsed := b.GetElapsedTime()
	next := getRandomValueFromInterval(b.RandomizationFactor, rand.Float64(), b.currentInterval)
	b.incrementCurrentInterval()
	if b.MaxElapsedTime != 0 && elapsed+next > b.MaxElapsedTime {
		return b.Stop
	}
	return next
}"}, "v4.3.0:NewExponentialBackOff": {"source_path": "exponential.go", "revision": "720b78985a65c0452fd37bb155c7cac4157a7c45", "source_sha256": "cd5e77b2c07db015cae3d8ad5224600f73db66b8d5f8bf1f75b73051689ddcfc", "first_line": 87, "last_line": 102, "quote": "func NewExponentialBackOff(opts ...ExponentialBackOffOpts) *ExponentialBackOff {
	b := &ExponentialBackOff{
		InitialInterval:     DefaultInitialInterval,
		RandomizationFactor: DefaultRandomizationFactor,
		Multiplier:          DefaultMultiplier,
		MaxInterval:         DefaultMaxInterval,
		MaxElapsedTime:      DefaultMaxElapsedTime,
		Stop:                Stop,
		Clock:               SystemClock,
	}
	for _, fn := range opts {
		fn(b)
	}
	b.Reset()
	return b
